<?php

namespace App\Domain\Shared;

use App\Domain\Exception\InvalidValueException;

/**
 * Base identity value object. Accepts UUIDs (generated by the app/MySQL) or numeric ids.
 */
abstract class AbstractId implements \Stringable
{
  private const UUID_PATTERN = '/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/';

  final protected function __construct(private string $value)
  {
  }

  public static function fromString(string $value): static
  {
    $normalized = strtolower(trim($value));
    if (!self::isValid($normalized)) {
      throw new InvalidValueException(static::label() . ' inválido.');
    }

    return new static($normalized);
  }

  public static function generate(): static
  {
    $bytes = random_bytes(16);
    $bytes[6] = chr((ord($bytes[6]) & 0x0f) | 0x40);
    $bytes[8] = chr((ord($bytes[8]) & 0x3f) | 0x80);

    return new static(vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)));
  }

  public static function isValid(?string $value): bool
  {
    if ($value === null) {
      return false;
    }

    $normalized = strtolower(trim($value));
    if ($normalized === '') {
      return false;
    }

    return ctype_digit($normalized) || preg_match(self::UUID_PATTERN, $normalized) === 1;
  }

  public function equals(self $other): bool
  {
    return $other::class === static::class && $other->value === $this->value;
  }

  public function value(): string
  {
    return $this->value;
  }

  public function __toString(): string
  {
    return $this->value;
  }

  /**
   * Human readable label used in validation messages.
   */
  protected static function label(): string
  {
    return 'Identificador';
  }
}
